def get_key(x):
    # Count the number of ones in the binary representation of x
    num_ones = len(int(x) if x > 0 else '0').count('1')
    # If the number of ones is zero, return the number itself
    if num_ones == 0:
        return x
    # Otherwise, return a tuple with the number of ones and the number
    return (num_ones, x)

